questions.solution:
const students = [
  { name: 'Amara', score: 88 },
  { name: 'Bayo',  score: 45 },
  { name: 'Chidi', score: 65 },
  { name: 'Dami',  score: 52 }
];

const withGrades = students.map(s => {
  let grade;
  if (s.score >= 80) grade = 'A';
  else if (s.score >= 60) grade = 'B';
  else if (s.score >= 50) grade = 'C';
  else grade = 'F';
  return { name: s.name, score: s.score, grade };
});

console.log(withGrades);

