questions.solution:
const transactions = [
  { id: 1, type: 'deposit',    amount: 5000 },
  { id: 2, type: 'withdrawal', amount: 1500 },
  { id: 3, type: 'deposit',    amount: 3000 },
  { id: 4, type: 'deposit',    amount: 8000 },
  { id: 5, type: 'withdrawal', amount: 2000 }
];

const grouped = transactions.reduce((acc, txn) => {
  if (!acc[txn.type]) acc[txn.type] = [];
  acc[txn.type].push(txn);
  return acc;
}, {});

console.log(grouped);
console.log(grouped.deposit.length);
